INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02','SC-02','Sample Collection','Tongue swab or sputum specimen produces a negative result that seems inconsistent with symptoms','សំណាកអណ្តាត ឬកំហាក ផ្តល់លទ្ធផលអវិជ្ជមាន ដែលមិនស៊ីនឹងរោគសញ្ញា','Follow full collection procedure: sputum ≥1 mL; tongue swab wiped/rotated for the full 30 seconds across ~3/4 of the tongue dorsum
