INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04-Q10','SC-04','Sample Collection','sputum collection steps','ជំហានយកកំហាក','1) Patient rinses with clear water for 10-15 seconds and spits it out.
2) Collect raw sputum in a sterile, leak-proof sputum cup.
3) At least 1 mL.

