INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-01-Q03','SS-01','Sample Storage','How long can I keep a tongue swab in the fridge?','អាចទុកសំណាកអណ្តាតក្នុងទូទឹកកកបានយូរប៉ុណ្ណា?','Up to 5 days at 2-8°C.
