INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-03-Q09','DO-03','Device Operation','insert card steps','ជំហានដាក់កាត','Open the lid, insert the card in the indicated direction and push it fully into the bottom slot (1 beep). Close the lid immediately.

