INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q07','PI-03','Product Information','Do I need a Thermolyse?','តើត្រូវការ Thermolyse ទេ?','Yes. The Thermolyse is used for the pretreatment step (3000 rpm, 75°C, 5 min).','បាទ/ចាស។ Thermolyse ត្រូវបានប្រើសម្រាប់ជំហាន pretreatment (3000 rpm, 75°C, ៥ នាទី)។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q08','PI-03','Product Information','What items are needed for sample collection?','ត្រូវការរបស់អ្វីខ្លះ សម្រាប់យកសំណាក?','A sputum cup or tongue swab, a timer, and the sampling guidance.','កែវកំហាក ឬដំបងសំឡីអណ្តាត នាឡិកាកំណត់ម៉ោង និងការណែនាំអំពីការយកសំណាក។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q09','PI-03','Product Information','How long does the test take?','តេស្តចំណាយពេលប៉ុន្មាន?','The run takes 5-25 minutes; total turnaround from sample to result is 30 minutes or less.','ការដំណើរការចំណាយ ៥-២៥ នាទី។ រយៈពេលសរុបពីសំណាកដល់លទ្ធផល មិនលើស ៣០ នាទី។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q10','PI-03','Product Information','What is the turnaround time?','រយៈពេលសរុបពីសំណាកដល់លទ្ធផលប៉ុន្មាន?','30 minutes or less.','មិនលើស ៣០ នាទី។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q11','PI-03','Product Information','How fast can I get a result?','អាចទទួលលទ្ធផលលឿនប៉ុណ្ណា?','The run takes as little as 5 minutes (5-25 min); total turnaround is 30 minutes or less.','ការដំណើរការចំណាយយ៉ាងលឿន ៥ នាទី (៥-២៥ នាទី)។ រយៈពេលសរុប មិនលើស ៣០ នាទី។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
