INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q13','PI-03','Product Information','How much hands-on time is needed?','ត្រូវចំណាយពេលធ្វើដោយដៃប៉ុន្មាន?','Within 2 minutes.','ក្នុងរយៈពេល ២ នាទី។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
