INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q17','PI-03','Product Information','What''s the overall workflow from sample to result?','លំដាប់ការងារទាំងមូល ពីសំណាកដល់លទ្ធផល យ៉ាងម៉េច?','Collect sample → mix sample → one-step pretreatment in the Thermolyse (3000 rpm, 75°C, 5 min) → run the test on the MiniDock.

Video (1 min): https://www.youtube.com/watch?v=q4P0pGz8hhM
Full video: https://www.youtube.com/watch?v=BT2BGlf3H8M&t=42s
Operation procedure: https://telegram-learning.lab-telegram-gemini-d1.workers.dev/files/02_KHANA_Pluslife_Procedure.pdf','យកសំណាក → លាយសំណាក → pretreatment មួយជំហានក្នុង Thermolyse (3000 rpm, 75°C, ៥ នាទី) → ធ្វើតេស្តលើ MiniDock។

វីដេអូខ្លី (១ នាទី)៖ https://www.youtube.com/watch?v=q4P0pGz8hhM
វីដេអូពេញ៖ https://www.youtube.com/watch?v=BT2BGlf3H8M&t=42s
ឯកសាររបៀបប្រើម៉ាស៊ីន (Operation procedure)៖ https://telegram-learning.lab-telegram-gemini-d1.workers.dev/files/02_KHANA_Pluslife_Procedure.pdf','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-04','PI-04','Product Information','Worker asks about device size or specifications','បុគ្គលិកសួរពីទំហំ ឬលក្ខណៈបច្ចេកទេសម៉ាស៊ីន','MiniDock Ultra: 101 x 91 x 65 mm, 240 g, palm-sized; Type-C, Wi-Fi and Bluetooth','MiniDock Ultra៖ 101 x 91 x 65 mm, 240 g, ទំហំប៉ុនបាតដៃ។ Type-C, Wi-Fi និង Bluetooth។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-04-Q01','PI-04','Product Information','How big is the MiniDock Ultra?','MiniDock Ultra ធំប៉ុនណា?','101 x 91 x 65 mm.','101 x 91 x 65 mm។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
