INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-04-Q04','PI-04','Product Information','Is the device portable?','តើម៉ាស៊ីនងាយយកតាមខ្លួនទេ?','Yes. It''s palm-sized: 101 x 91 x 65 mm, 240 g.','បាទ/ចាស។ វាមានទំហំប៉ុនបាតដៃ៖ 101 x 91 x 65 mm, 240 g។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-04-Q05','PI-04','Product Information','What are the MiniDock Ultra specifications?','លក្ខណៈបច្ចេកទេស MiniDock Ultra មានអ្វីខ្លះ?','101 x 91 x 65 mm, 240 g, Type-C and Wi-Fi connectivity.','101 x 91 x 65 mm, 240 g, ភ្ជាប់តាម Type-C និង Wi-Fi។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05','PI-05','Product Information','Worker asks about UPS specifications','បុគ្គលិកសួរពីលក្ខណៈបច្ចេកទេស UPS','600W (UPS-PL-600W): 270 x 210 x 185 mm, 6.5 kg, LiFePO4 576 Wh. 1200W (UPS-PL-1200W): 280 x 245 x 250 mm, 11.22 kg, LiFePO4 1152 Wh. Both: 220 V AC ±5% pure sine wave; DC 12 V/10 A; 2 × USB QC 3.0 (max 12 V/1.5 A); Type-C1 PD/QC 3.0 (max 30 W); Type-C2 PD (max 100 W)','600W (UPS-PL-600W)៖ 270 x 210 x 185 mm, 6.5 kg, ថ្ម LiFePO4 576 Wh។ 1200W (UPS-PL-1200W)៖ 280 x 245 x 250 mm, 11.22 kg, ថ្ម LiFePO4 1152 Wh។ ទាំងពីរ៖ 220 V AC ±5% pure sine wave; DC 12 V/10 A; USB QC 3.0 ចំនួន ២ (អតិបរមា 12 V/1.5 A); Type-C1 PD/QC 3.0 (អតិបរមា 30 W); Type-C2 PD (អតិបរមា 100 W)។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05-Q01','PI-05','Product Information','What are the UPS specifications?','លក្ខណៈបច្ចេកទេស UPS មានអ្វីខ្លះ?','600W (UPS-PL-600W): 270 x 210 x 185 mm, 6.5 kg, LiFePO4 576 Wh.
1200W (UPS-PL-1200W): 280 x 245 x 250 mm, 11.22 kg, LiFePO4 1152 Wh.
Both: 220 V AC ±5% pure sine wave; DC 12 V/10 A; USB QC 3.0; Type-C up to 100 W; charges via DC 12-24 V or Type-C PD.','600W (UPS-PL-600W)៖ 270 x 210 x 185 mm, 6.5 kg, ថ្ម LiFePO4 576 Wh។
1200W (UPS-PL-1200W)៖ 280 x 245 x 250 mm, 11.22 kg, ថ្ម LiFePO4 1152 Wh។
ទាំងពីរ៖ 220 V AC ±5% pure sine wave; DC 12 V/10 A; USB QC 3.0; Type-C រហូតដល់ 100 W; សាកថ្មតាម DC 12-24 V ឬ Type-C PD។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05-Q02','PI-05','Product Information','How heavy is the 600W UPS?','UPS 600W ធ្ងន់ប៉ុន្មាន?','6.5 kg.','6.5 kg។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05-Q03','PI-05','Product Information','What outputs does the UPS have?','UPS មានរន្ធចេញភ្លើងអ្វីខ្លះ?','AC 220 V ±5% (pure sine wave), DC 12 V/10 A, 2 × USB QC 3.0 (max 12 V/1.5 A), Type-C1 PD/QC 3.0 (max 30 W), Type-C2 PD (max 100 W).','AC 220 V ±5% (pure sine wave), DC 12 V/10 A, USB QC 3.0 ចំនួន ២ (អតិបរមា 12 V/1.5 A), Type-C1 PD/QC 3.0 (អតិបរមា 30 W), Type-C2 PD (អតិបរមា 100 W)។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05-Q04','PI-05','Product Information','What battery does the UPS use?','UPS ប្រើថ្មប្រភេទអ្វី?','LiFePO4: 576 Wh (600W) or 1152 Wh (1200W).','LiFePO4៖ 576 Wh (600W) ឬ 1152 Wh (1200W)។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05-Q05','PI-05','Product Information','What is the UPS AC output voltage?','តង់ស្យុង AC ចេញពី UPS ប៉ុន្មាន?','220 V AC ±5%, pure sine wave.','220 V AC ±5%, pure sine wave។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05-Q06','PI-05','Product Information','UPS model numbers','លេខម៉ូដែល UPS','UPS-PL-600W and UPS-PL-1200W.','UPS-PL-600W និង UPS-PL-1200W។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05-Q07','PI-05','Product Information','How big is the 1200W UPS?','UPS 1200W ធំប៉ុនណា?','280 x 245 x 250 mm (11.22 kg).','280 x 245 x 250 mm (11.22 kg)។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06','PI-06','Product Information','Worker asks how accurate the test is','បុគ្គលិកសួរថាតេស្តនេះត្រឹមត្រូវប៉ុណ្ណា','Against the microbiological reference standard (N=1,266): sputum swab sensitivity 86.7%, specificity 98.0%; tongue swab 80.7% / 99.6%. Xpert Ultra 89.4% / 99.0% (sensitivity difference p=0.11). Smear microscopy sensitivity 62.4% vs 80.7% for tongue swab (p<0.001). Source: R2D2 TB Network stage analysis report, 14 Jul 2025','ធៀបនឹងស្តង់ដារយោងមីក្រូជីវសាស្ត្រ (N=1,266)៖ សំណាកកំហាក ភាពរសើប (sensitivity) 86.7% ភាពជាក់លាក់ (specificity) 98.0%។ សំណាកអណ្តាត 80.7% / 99.6%។ Xpert Ultra 89.4% / 99.0% (ភាពខុសគ្នានៃភាពរសើប p=0.11)។ ការពិនិត្យកំហាកតាមមីក្រូទស្សន៍ (smear) ភាពរសើប 62.4% ធៀបនឹង 80.7% សម្រាប់សំណាកអណ្តាត (p<0.001)។ ប្រភព៖ របាយការណ៍វិភាគដំណាក់កាល R2D2 TB Network ថ្ងៃទី ១៤ ខែកក្កដា ឆ្នាំ ២០២៥។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q01','PI-06','Product Information','How accurate is the MiniDock MTB Test?','MiniDock MTB Test ត្រឹមត្រូវប៉ុណ្ណា?','Against the microbiological reference standard (N=1,266):
Sputum swab: sensitivity 86.7%, specificity 98.0%.
Tongue swab: sensitivity 80.7%, specificity 99.6%.
(R2D2 TB Network study, Jul 2025)','ធៀបនឹងស្តង់ដារយោងមីក្រូជីវសាស្ត្រ (N=1,266)៖
សំណាកកំហាក៖ ភាពរសើប 86.7% ភាពជាក់លាក់ 98.0%។
សំណាកអណ្តាត៖ ភាពរសើប 80.7% ភាពជាក់លាក់ 99.6%។
(ការសិក្សា R2D2 TB Network ខែកក្កដា ២០២៥)','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q02','PI-06','Product Information','What is the sensitivity of the sputum test?','ភាពរសើប (sensitivity) នៃតេស្តកំហាកប៉ុន្មាន?','86.7% (sputum swab, against the microbiological reference standard).','86.7% (សំណាកកំហាក ធៀបនឹងស្តង់ដារយោងមីក្រូជីវសាស្ត្រ)។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q03','PI-06','Product Information','What is the specificity of the tongue swab test?','ភាពជាក់លាក់ (specificity) នៃតេស្តសំណាកអណ្តាតប៉ុន្មាន?','99.6% (tongue swab, against the microbiological reference standard).','99.6% (សំណាកអណ្តាត ធៀបនឹងស្តង់ដារយោងមីក្រូជីវសាស្ត្រ)។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q04','PI-06','Product Information','How does it compare with Xpert Ultra?','ប្រៀបធៀបជាមួយ Xpert Ultra យ៉ាងម៉េច?','Comparable. Sputum swab: 86.7% sensitivity / 98.0% specificity; Xpert Ultra: 89.4% / 99.0%. The sensitivity difference wasn''t significant (p=0.11).','ប្រហាក់ប្រហែលគ្នា។ សំណាកកំហាក៖ ភាពរសើប 86.7% / ភាពជាក់លាក់ 98.0%។ Xpert Ultra៖ 89.4% / 99.0%។ ភាពខុសគ្នានៃភាពរសើប មិនមានសារៈសំខាន់ស្ថិតិទេ (p=0.11)។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q05','PI-06','Product Information','How does the tongue swab test compare with smear microscopy?','តេស្តសំណាកអណ្តាត ប្រៀបធៀបជាមួយការពិនិត្យកំហាកតាមមីក្រូទស្សន៍យ៉ាងម៉េច?','Tongue swab sensitivity 80.7% vs 62.4% for smear microscopy (p<0.001). Specificity 99.6% vs 99.8%.','ភាពរសើបនៃសំណាកអណ្តាត 80.7% ធៀបនឹង 62.4% សម្រាប់ការពិនិត្យកំហាកតាមមីក្រូទស្សន៍ (p<0.001)។ ភាពជាក់លាក់ 99.6% ធៀបនឹង 99.8%។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q06','PI-06','Product Information','clinical performance data','ទិន្នន័យប្រសិទ្ធភាពគ្លីនិក','Against the microbiological reference standard (N=1,266):
Sputum swab: sensitivity 86.7%, specificity 98.0%.
Tongue swab: sensitivity 80.7%, specificity 99.6%.
(R2D2 TB Network study, Jul 2025)','ធៀបនឹងស្តង់ដារយោងមីក្រូជីវសាស្ត្រ (N=1,266)៖
សំណាកកំហាក៖ ភាពរសើប 86.7% ភាពជាក់លាក់ 98.0%។
សំណាកអណ្តាត៖ ភាពរសើប 80.7% ភាពជាក់លាក់ 99.6%។
(ការសិក្សា R2D2 TB Network ខែកក្កដា ២០២៥)','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q07','PI-06','Product Information','Which study does the performance data come from?','ទិន្នន័យប្រសិទ្ធភាពនេះ មកពីការសិក្សាណា?','R2D2 TB Network, Clinical Performance Study of MiniDock MTB Test in High TB Burden Settings: stage analysis report, 14 Jul 2025 (N=1,266).','R2D2 TB Network, Clinical Performance Study of MiniDock MTB Test in High TB Burden Settings៖ របាយការណ៍វិភាគដំណាក់កាល ថ្ងៃទី ១៤ ខែកក្កដា ឆ្នាំ ២០២៥ (N=1,266)។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q08','PI-06','Product Information','Is the tongue swab as sensitive as sputum?','តើសំណាកអណ្តាតរសើបដូចកំហាកទេ?','No. In the same study, tongue swab sensitivity was 80.7% vs 86.7% for sputum swab.','មិនស្មើទេ។ ក្នុងការសិក្សាដដែល ភាពរសើបនៃសំណាកអណ្តាតគឺ 80.7% ធៀបនឹង 86.7% សម្រាប់សំណាកកំហាក។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-01','RG-01','Regulatory & Guidelines','Worker asks whether the test is covered by WHO guidance','បុគ្គលិកសួរថាតេស្តនេះមាននៅក្នុងគោលការណ៍ណែនាំរបស់ WHO ឬអត់','The MiniDock MTB Test is an NPOC-NAAT (near point-of-care nucleic acid amplification test), a class added to the WHO TB guidelines (Module 3: Diagnosis) as an initial test for people with TB symptoms or who screen positive. Sputum preferred; tongue swab if no sputum. Positive → drug-susceptibility testing and care; negative → clinical assessment / follow-up','MiniDock MTB Test ជា NPOC-NAAT (តេស្តពង្រីកអាស៊ីតនុយក្លេអ៊ីក នៅជិតកន្លែងផ្តល់សេវា) ជាប្រភេទតេស្តដែលត្រូវបានបន្ថែមក្នុងគោលការណ៍ណែនាំជំងឺរបេងរបស់អង្គការសុខភាពពិភពលោក (WHO) (Module 3: Diagnosis) ជាតេស្តដំបូងសម្រាប់អ្នកមានរោគសញ្ញាជំងឺរបេង ឬអ្នកដែលការពិនិត្យស្រាវជ្រាវវិជ្ជមាន។ កំហាកត្រូវបានគេពេញចិត្តជាង។ សំណាកអណ្តាត បើគ្មានកំហាក។ វិជ្ជមាន → ការធ្វើតេស្តរកភាពស៊ាំនឹងថ្នាំ និងការថែទាំ។ អវិជ្ជមាន → ការវាយតម្លៃគ្លីនិក / ការតាមដាន។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-01-Q01','RG-01','Regulatory & Guidelines','Is the MiniDock MTB Test covered by WHO guidance?','តើ MiniDock MTB Test មាននៅក្នុងគោលការណ៍ណែនាំរបស់ WHO ទេ?','Yes. The MiniDock MTB Test is an NPOC-NAAT, a test class added to the WHO TB guidelines (Module 3: Diagnosis).','បាទ/ចាស។ MiniDock MTB Test ជា NPOC-NAAT ដែលជាប្រភេទតេស្តដែលត្រូវបានបន្ថែមក្នុងគោលការណ៍ណែនាំជំងឺរបេងរបស់ WHO (Module 3: Diagnosis)។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-01-Q02','RG-01','Regulatory & Guidelines','What is an NPOC-NAAT?','NPOC-NAAT ជាអ្វី?','Near point-of-care nucleic acid amplification test: a new WHO test class for near-patient TB testing in decentralised settings.','តេស្តពង្រីកអាស៊ីតនុយក្លេអ៊ីក នៅជិតកន្លែងផ្តល់សេវា (Near point-of-care NAAT)៖ ជាប្រភេទតេស្តថ្មីរបស់ WHO សម្រាប់ធ្វើតេស្តជំងឺរបេងនៅជិតអ្នកជំងឺ ក្នុងមូលដ្ឋានសុខាភិបាលថ្នាក់ក្រោម។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-01-Q03','RG-01','Regulatory & Guidelines','What does WHO say about tongue swabs?','WHO និយាយយ៉ាងម៉េចពីសំណាកអណ្តាត?','Sputum is preferred; use a tongue swab when sputum can''t be obtained.','កំហាកត្រូវបានគេពេញចិត្តជាង។ ប្រើសំណាកអណ្តាត ពេលមិនអាចយកកំហាកបាន។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-01-Q04','RG-01','Regulatory & Guidelines','Where does the test fit in the TB diagnostic algorithm?','តេស្តនេះស្ថិតនៅត្រង់ណាក្នុងក្បួនដោះស្រាយរោគវិនិច្ឆ័យជំងឺរបេង?','As the initial test for people with TB symptoms or who screen positive. Positive → drug-susceptibility testing and care; negative → clinical assessment / follow-up.

Result decision guide: [Result Decision Guide - Pending]','ជាតេស្តដំបូងសម្រាប់អ្នកមានរោគសញ្ញាជំងឺរបេង ឬអ្នកដែលការពិនិត្យស្រាវជ្រាវវិជ្ជមាន។ វិជ្ជមាន → ការធ្វើតេស្តរកភាពស៊ាំនឹងថ្នាំ និងការថែទាំ។ អវិជ្ជមាន → ការវាយតម្លៃគ្លីនិក / ការតាមដាន។

ឯកសារណែនាំការសម្រេចចិត្តតាមលទ្ធផល (Result decision guide)៖ [ឯកសារកំពុងរៀបចំ - Pending]','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-01-Q05','RG-01','Regulatory & Guidelines','WHO guideline','គោលការណ៍ណែនាំ WHO','WHO added NPOC-NAATs (including the MiniDock MTB Test) as an initial test for people with TB symptoms or who screen positive. Sputum is preferred; tongue swab if no sputum. Positive → drug-susceptibility testing and care; negative → clinical assessment / follow-up.

Result decision guide: [Result Decision Guide - Pending]','WHO បានបន្ថែម NPOC-NAATs (រួមទាំង MiniDock MTB Test) ជាតេស្តដំបូងសម្រាប់អ្នកមានរោគសញ្ញាជំងឺរបេង ឬអ្នកដែលការពិនិត្យស្រាវជ្រាវវិជ្ជមាន។ កំហាកត្រូវបានគេពេញចិត្តជាង។ សំណាកអណ្តាត បើគ្មានកំហាក។ វិជ្ជមាន → ការធ្វើតេស្តរកភាពស៊ាំនឹងថ្នាំ និងការថែទាំ។ អវិជ្ជមាន → ការវាយតម្លៃគ្លីនិក / ការតាមដាន។

ឯកសារណែនាំការសម្រេចចិត្តតាមលទ្ធផល (Result decision guide)៖ [ឯកសារកំពុងរៀបចំ - Pending]','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-01-Q06','RG-01','Regulatory & Guidelines','Can it be used as the initial test?','តើអាចប្រើវាជាតេស្តដំបូងបានទេ?','Yes. WHO guidance supports NPOC-NAATs as the initial test for people with symptoms or who screen positive.','បាទ/ចាស។ គោលការណ៍ណែនាំរបស់ WHO គាំទ្រ NPOC-NAATs ជាតេស្តដំបូងសម្រាប់អ្នកមានរោគសញ្ញា ឬអ្នកដែលការពិនិត្យស្រាវជ្រាវវិជ្ជមាន។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-02','RG-02','Regulatory & Guidelines','Worker asks about ERPD, Global Fund procurement or WHO PQ status','បុគ្គលិកសួរពីស្ថានភាព ERPD Global Fund ឬ WHO PQ','Global Fund letter, 11 Jul 2025: ERPD Category 2, procurement allowed for 12 months (until 10 Jul 2026). Pluslife''s March 2026 brief lists an ERPD listing (sputum + tongue swab) in Feb 2026 and expected WHO PQ listing in Dec 2026. Confirm the current status before quoting','លិខិតរបស់ Global Fund ថ្ងៃទី ១១ ខែកក្កដា ឆ្នាំ ២០២៥៖ ERPD ប្រភេទទី ២ អនុញ្ញាតឲ្យលទ្ធកម្មរយៈពេល ១២ ខែ (រហូតដល់ ១០ កក្កដា ២០២៦)។ សេចក្តីសង្ខេបរបស់ Pluslife ខែមីនា ឆ្នាំ ២០២៦ បង្ហាញការចុះបញ្ជី ERPD (កំហាក + សំណាកអណ្តាត) នៅខែកុម្ភៈ ២០២៦ និងរំពឹងថានឹងចុះបញ្ជី WHO PQ នៅខែធ្នូ ២០២៦។ សូមផ្ទៀងផ្ទាត់ស្ថានភាពបច្ចុប្បន្នមុននឹងលើកឡើង។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-02-Q01','RG-02','Regulatory & Guidelines','What is the ERPD status of the MiniDock MTB Test?','ស្ថានភាព ERPD របស់ MiniDock MTB Test យ៉ាងម៉េច?','Global Fund letter, 11 Jul 2025: ERPD Category 2, procurement allowed for a time-limited 12 months (until 10 July 2026). Pluslife''s March 2026 brief lists an ERPD listing (sputum + tongue swab) in Feb 2026. Please confirm the current status before quoting.','លិខិតរបស់ Global Fund ថ្ងៃទី ១១ ខែកក្កដា ឆ្នាំ ២០២៥៖ ERPD ប្រភេទទី ២ អនុញ្ញាតឲ្យលទ្ធកម្មក្នុងរយៈពេលកំណត់ ១២ ខែ (រហូតដល់ ១០ កក្កដា ២០២៦)។ សេចក្តីសង្ខេបរបស់ Pluslife ខែមីនា ឆ្នាំ ២០២៦ បង្ហាញការចុះបញ្ជី ERPD (កំហាក + សំណាកអណ្តាត) នៅខែកុម្ភៈ ២០២៦។ សូមផ្ទៀងផ្ទាត់ស្ថានភាពបច្ចុប្បន្នមុននឹងលើកឡើង។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-02-Q02','RG-02','Regulatory & Guidelines','Can the test be procured with Global Fund money?','តើអាចទិញតេស្តនេះដោយថវិកា Global Fund បានទេ?','Unclear. The 11 Jul 2025 ERPD Category 2 approval allowed Global Fund/Unitaid procurement until 10 July 2026, after ad hoc review and a no-objection letter. The current status needs to be confirmed.','មិនច្បាស់ទេ។ ការអនុម័ត ERPD ប្រភេទទី ២ ថ្ងៃទី ១១ ខែកក្កដា ឆ្នាំ ២០២៥ អនុញ្ញាតឲ្យ Global Fund/Unitaid ធ្វើលទ្ធកម្មរហូតដល់ ១០ កក្កដា ២០២៦ ក្រោយការពិនិត្យពិសេស និងលិខិតគ្មានការជំទាស់។ ស្ថានភាពបច្ចុប្បន្នត្រូវការផ្ទៀងផ្ទាត់។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-02-Q03','RG-02','Regulatory & Guidelines','What ERPD category is the product in?','ផលិតផលនេះស្ថិតក្នុង ERPD ប្រភេទណា?','Category 2 (Global Fund letter, 11 Jul 2025). Please confirm the current status.','ប្រភេទទី ២ (លិខិតរបស់ Global Fund ថ្ងៃទី ១១ ខែកក្កដា ឆ្នាំ ២០២៥)។ សូមផ្ទៀងផ្ទាត់ស្ថានភាពបច្ចុប្បន្ន។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-02-Q04','RG-02','Regulatory & Guidelines','Is the product WHO prequalified?','តើផលិតផលនេះមាន WHO prequalification ហើយឬនៅ?','Unclear. As of the March 2026 brief, WHO PQ listing was expected in December 2026. Please confirm the current status.','មិនច្បាស់ទេ។ យោងតាមសេចក្តីសង្ខេបខែមីនា ឆ្នាំ ២០២៦ ការចុះបញ្ជី WHO PQ ត្រូវបានរំពឹងនៅខែធ្នូ ឆ្នាំ ២០២៦។ សូមផ្ទៀងផ្ទាត់ស្ថានភាពបច្ចុប្បន្ន។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-02-Q05','RG-02','Regulatory & Guidelines','ERPD','ERPD','Global Fund letter, 11 Jul 2025: ERPD Category 2, procurement allowed for a time-limited 12 months (until 10 July 2026). Pluslife''s March 2026 brief lists an ERPD listing (sputum + tongue swab) in Feb 2026. Please confirm the current status before quoting.','លិខិតរបស់ Global Fund ថ្ងៃទី ១១ ខែកក្កដា ឆ្នាំ ២០២៥៖ ERPD ប្រភេទទី ២ អនុញ្ញាតឲ្យលទ្ធកម្មក្នុងរយៈពេលកំណត់ ១២ ខែ (រហូតដល់ ១០ កក្កដា ២០២៦)។ សេចក្តីសង្ខេបរបស់ Pluslife ខែមីនា ឆ្នាំ ២០២៦ បង្ហាញការចុះបញ្ជី ERPD (កំហាក + សំណាកអណ្តាត) នៅខែកុម្ភៈ ២០២៦។ សូមផ្ទៀងផ្ទាត់ស្ថានភាពបច្ចុប្បន្នមុននឹងលើកឡើង។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-02-Q06','RG-02','Regulatory & Guidelines','When does the ERPD period end?','រយៈពេល ERPD ផុតកំណត់ពេលណា?','The 11 Jul 2025 approval ran until 10 July 2026. Pluslife''s March 2026 brief lists a new ERPD listing (sputum + tongue swab) in Feb 2026, with no end date given. Please confirm the current status.','ការអនុម័តថ្ងៃទី ១១ ខែកក្កដា ឆ្នាំ ២០២៥ មានសុពលភាពរហូតដល់ ១០ កក្កដា ២០២៦។ សេចក្តីសង្ខេបរបស់ Pluslife ខែមីនា ឆ្នាំ ២០២៦ បង្ហាញការចុះបញ្ជី ERPD ថ្មី (កំហាក + សំណាកអណ្តាត) នៅខែកុម្ភៈ ២០២៦ ដោយមិនបញ្ជាក់ថ្ងៃផុតកំណត់។ សូមផ្ទៀងផ្ទាត់ស្ថានភាពបច្ចុប្បន្ន។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
