INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-12-Q03','MO-12','Mis-operation','open lid mid test','បើកគម្របពាក់កណ្តាលតេស្ត','Opening the lid during a test is strictly prohibited. With MiniDock Ultra, the instrument stops the test and reports an invalid result when the lid is opened.
