INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-14','SC-14','Sample Collection','Worker asks how to collect a sputum sample','បុគ្គលិកសួរពីរបៀបយកសំណាកកំហាក','1. Rinse mouth.
