INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-15-Q05','SC-15','Sample Collection','tongue swab how','សំណាកអណ្តាត ធ្វើម៉េច','1. Ensure no eating or drinking within 30 minutes.
