INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-16-Q02','SC-16','Sample Collection','Xpert sample left over, use for Pluslife?','សំណាក Xpert នៅសល់ ប្រើសម្រាប់ Pluslife បានទេ?','No, not if it was treated with Xpert''s liquefaction reagent. Use the original (untreated) sputum sample.
