INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-02-Q05','SS-02','Sample Storage','sample store room temp how long','រក្សាទុកសំណាកនៅសីតុណ្ហភាពបន្ទប់ បានរយៈពេលប៉ុន្មាន','DNA samples: room temperature (10–30 °C) for 24 hours.
