INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-15','CP-15','Card Preparation','Card leaks during sample loading','កាតលេចធ្លាយពេលដាក់សំណាកចូល','Immediately seal the card and wipe off the leaked liquid. Disinfect the area with 75% alcohol. After changing gloves, open a new card and perform the test again.
