INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-13','DO-13','Device Operation','Worker asks what to watch out for while running a test','បុគ្គលិកសួរថាត្រូវប្រុងប្រយ័ត្នអ្វីខ្លះ ពេលកំពុងធ្វើតេស្ត','1. After putting the test card in the device, close the lid within 30 seconds.
