INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-08-Q03','PI-08','Product Information','product list pls','សូមបញ្ជីផលិតផល','Please check the Pluslife official website: https://www.pluslife.com/testcards','សូមពិនិត្យគេហទំព័រផ្លូវការរបស់ Pluslife៖ https://www.pluslife.com/testcards','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
