INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-09','PI-09','Product Information','Worker asks about device size or weight','បុគ្គលិកសួរអំពីទំហំ ឬទម្ងន់ម៉ាស៊ីន','MiniDock Ultra: 101 × 91 × 65 mm, weight 240 g — about the same as an iPhone 14 Pro.','MiniDock Ultra៖ 101 × 91 × 65 mm ទម្ងន់ 240 g — ប្រហែលស្មើនឹង iPhone 14 Pro។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-09-Q01','PI-09','Product Information','How big is the MiniDock Ultra?','តើ MiniDock Ultra ធំប៉ុណ្ណា?','MiniDock Ultra: 101 × 91 × 65 mm.','MiniDock Ultra៖ 101 × 91 × 65 mm។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-09-Q02','PI-09','Product Information','How heavy is the device?','តើម៉ាស៊ីនធ្ងន់ប៉ុណ្ណា?','The MiniDock Ultra weighs 240 g — about the same as an iPhone 14 Pro.','MiniDock Ultra មានទម្ងន់ 240 g — ប្រហែលស្មើនឹង iPhone 14 Pro។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-09-Q03','PI-09','Product Information','device size and weight','ទំហំ និងទម្ងន់ម៉ាស៊ីន','MiniDock Ultra: 101 × 91 × 65 mm, weight 240 g — about the same as an iPhone 14 Pro.','MiniDock Ultra៖ 101 × 91 × 65 mm ទម្ងន់ 240 g — ប្រហែលស្មើនឹង iPhone 14 Pro។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-09-Q04','PI-09','Product Information','Is the device heavy to carry for outreach?','តើម៉ាស៊ីនធ្ងន់សម្រាប់យកទៅសកម្មភាពសហគមន៍ឬទេ?','Not sure — that depends on your situation. For reference: MiniDock Ultra: 101 × 91 × 65 mm, weight 240 g — about the same as an iPhone 14 Pro.','មិនច្បាស់ទេ — វាអាស្រ័យលើស្ថានភាពរបស់អ្នក។ សម្រាប់ជាឯកសារយោង៖ MiniDock Ultra៖ 101 × 91 × 65 mm ទម្ងន់ 240 g — ប្រហែលស្មើនឹង iPhone 14 Pro។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-09-Q05','PI-09','Product Information','dimension of minidock ultra?','វិមាត្រនៃ minidock ultra?','MiniDock Ultra: 101 × 91 × 65 mm, weight 240 g — about the same as an iPhone 14 Pro.','MiniDock Ultra៖ 101 × 91 × 65 mm ទម្ងន់ 240 g — ប្រហែលស្មើនឹង iPhone 14 Pro។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-10','PI-10','Product Information','Worker asks how long one test takes','បុគ្គលិកសួរថាតេស្តមួយចំណាយពេលប៉ុន្មាន','It depends on which product you are using.
Single-target products: a negative result takes 25–35 minutes (25 minutes for MTB); a positive result is reported within 5–25 minutes (5–20 minutes for MTB).
Multiplex products: a negative result takes 35 minutes; for a positive result, the time is determined by when the last target is detected.','វាអាស្រ័យលើផលិតផលដែលអ្នកកំពុងប្រើ។
ផលិតផលគោលដៅតែមួយ (Single-target)៖ លទ្ធផលអវិជ្ជមានត្រូវការ ២៥–៣៥ នាទី (២៥ នាទីសម្រាប់ MTB)។ លទ្ធផលវិជ្ជមានចេញក្នុងរយៈពេល ៥–២៥ នាទី (៥–២០ នាទីសម្រាប់ MTB)។
ផលិតផលពហុគោលដៅ (Multiplex)៖ លទ្ធផលអវិជ្ជមានត្រូវការ ៣៥ នាទី។ សម្រាប់លទ្ធផលវិជ្ជមាន ពេលវេលាត្រូវបានកំណត់ដោយពេលដែលរកឃើញគោលដៅចុងក្រោយ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-10-Q01','PI-10','Product Information','How long does one TB test take?','តើតេស្តជំងឺរបេងមួយចំណាយពេលប៉ុន្មាន?','For MTB: a negative result takes 25 minutes; a positive result is reported within 5–20 minutes.','សម្រាប់ MTB៖ លទ្ធផលអវិជ្ជមានត្រូវការ ២៥ នាទី។ លទ្ធផលវិជ្ជមានចេញក្នុងរយៈពេល ៥–២០ នាទី។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-10-Q02','PI-10','Product Information','how long until result come out','តើរយៈពេលប៉ុន្មានទើបលទ្ធផលចេញ','For MTB: a negative result takes 25 minutes; a positive result is reported within 5–20 minutes.','សម្រាប់ MTB៖ លទ្ធផលអវិជ្ជមានត្រូវការ ២៥ នាទី។ លទ្ធផលវិជ្ជមានចេញក្នុងរយៈពេល ៥–២០ នាទី។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-10-Q03','PI-10','Product Information','Why did my positive come out faster than the negative ones?','ហេតុអ្វីបានជាលទ្ធផលវិជ្ជមានរបស់ខ្ញុំចេញលឿនជាងលទ្ធផលអវិជ្ជមាន?','A positive result is reported earlier. For MTB: a negative result takes 25 minutes; a positive result is reported within 5–20 minutes.','លទ្ធផលវិជ្ជមានចេញលឿនជាង។ សម្រាប់ MTB៖ លទ្ធផលអវិជ្ជមានត្រូវការ ២៥ នាទី។ លទ្ធផលវិជ្ជមានចេញក្នុងរយៈពេល ៥–២០ នាទី។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-10-Q04','PI-10','Product Information','Is 25 minutes normal for a negative MTB result?','តើ ២៥ នាទីជារឿងធម្មតាសម្រាប់លទ្ធផល MTB អវិជ្ជមានឬទេ?','Yes. For MTB: a negative result takes 25 minutes; a positive result is reported within 5–20 minutes.','បាទ/ចាស។ សម្រាប់ MTB៖ លទ្ធផលអវិជ្ជមានត្រូវការ ២៥ នាទី។ លទ្ធផលវិជ្ជមានចេញក្នុងរយៈពេល ៥–២០ នាទី។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-10-Q05','PI-10','Product Information','How long does a test take on a multiplex card?','តើតេស្តលើកាតពហុគោលដៅ (multiplex) ចំណាយពេលប៉ុន្មាន?','Multiplex products: a negative result takes 35 minutes; for a positive result, the time is determined by when the last target is detected.','ផលិតផលពហុគោលដៅ (Multiplex)៖ លទ្ធផលអវិជ្ជមានត្រូវការ ៣៥ នាទី។ សម្រាប់លទ្ធផលវិជ្ជមាន ពេលវេលាត្រូវបានកំណត់ដោយពេលដែលរកឃើញគោលដៅចុងក្រោយ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-10-Q06','PI-10','Product Information','test time?','ពេលវេលាតេស្ត?','For MTB: a negative result takes 25 minutes; a positive result is reported within 5–20 minutes.','សម្រាប់ MTB៖ លទ្ធផលអវិជ្ជមានត្រូវការ ២៥ នាទី។ លទ្ធផលវិជ្ជមានចេញក្នុងរយៈពេល ៥–២០ នាទី។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-11','PI-11','Product Information','Worker asks which technology Pluslife uses','បុគ្គលិកសួរថា Pluslife ប្រើបច្ចេកវិទ្យាអ្វី','Pluslife POCT products are based on Pluslife''s proprietary RHAM technology, which is an optimization built on LAMP technology.
The RHAM reporting system consists of a nuclease and a probe. The probe is made of modified oligonucleotides and binds specifically to its complementary strand. When single-stranded, the probe is not cleaved by the nuclease; once bound to the complementary strand, the nuclease cleaves the probe, generating a fluorescence signal. As the reaction proceeds, new probes bind to complementary strands and continue new cycles, accumulating fluorescence. The instrument then detects the fluorescence signal and automatically analyzes the result.','ផលិតផល POCT របស់ Pluslife ផ្អែកលើបច្ចេកវិទ្យា RHAM ជាកម្មសិទ្ធិផ្ទាល់របស់ Pluslife ដែលជាការធ្វើឲ្យប្រសើរឡើងដោយផ្អែកលើបច្ចេកវិទ្យា LAMP។
ប្រព័ន្ធរាយការណ៍ RHAM មានអង់ស៊ីម nuclease និងប្រូប (probe) មួយ។ ប្រូបត្រូវបានផលិតពី oligonucleotides ដែលបានកែប្រែ ហើយភ្ជាប់ដោយជាក់លាក់ជាមួយខ្សែបំពេញបន្ថែមរបស់វា។ ពេលនៅជាខ្សែតែមួយ ប្រូបមិនត្រូវបានកាត់ដោយ nuclease ទេ។ ពេលភ្ជាប់ជាមួយខ្សែបំពេញបន្ថែមហើយ nuclease កាត់ប្រូប បង្កើតសញ្ញាពន្លឺ (fluorescence)។ នៅពេលប្រតិកម្មដំណើរការ ប្រូបថ្មីភ្ជាប់ជាមួយខ្សែបំពេញបន្ថែម ហើយបន្តវដ្តថ្មី ប្រមូលផ្តុំហ្វ្លុយអូរ៉េសង់។ បន្ទាប់មកម៉ាស៊ីនរកឃើញសញ្ញាពន្លឺ (fluorescence) ហើយវិភាគលទ្ធផលដោយស្វ័យប្រវត្តិ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-11-Q01','PI-11','Product Information','What technology does Pluslife use?','តើ Pluslife ប្រើបច្ចេកវិទ្យាអ្វី?','Pluslife POCT products are based on Pluslife''s proprietary RHAM technology, which is an optimization built on LAMP technology.','ផលិតផល POCT របស់ Pluslife ផ្អែកលើបច្ចេកវិទ្យា RHAM ជាកម្មសិទ្ធិផ្ទាល់របស់ Pluslife ដែលជាការធ្វើឲ្យប្រសើរឡើងដោយផ្អែកលើបច្ចេកវិទ្យា LAMP។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-11-Q02','PI-11','Product Information','Is this PCR or LAMP?','តើនេះជា PCR ឬ LAMP?','It is RHAM, Pluslife''s proprietary technology, which is an optimization built on LAMP technology.','វាគឺ RHAM ជាបច្ចេកវិទ្យាជាកម្មសិទ្ធិផ្ទាល់របស់ Pluslife ដែលជាការធ្វើឲ្យប្រសើរឡើងដោយផ្អែកលើបច្ចេកវិទ្យា LAMP។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-11-Q03','PI-11','Product Information','Is RHAM based on LAMP?','តើ RHAM ផ្អែកលើ LAMP ឬទេ?','Yes. Pluslife POCT products are based on Pluslife''s proprietary RHAM technology, which is an optimization built on LAMP technology.','បាទ/ចាស។ ផលិតផល POCT របស់ Pluslife ផ្អែកលើបច្ចេកវិទ្យា RHAM ជាកម្មសិទ្ធិផ្ទាល់របស់ Pluslife ដែលជាការធ្វើឲ្យប្រសើរឡើងដោយផ្អែកលើបច្ចេកវិទ្យា LAMP។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-11-Q04','PI-11','Product Information','How does RHAM produce the fluorescence signal?','តើ RHAM បង្កើតសញ្ញាពន្លឺ (fluorescence)ដោយរបៀបណា?','The RHAM reporting system consists of a nuclease and a probe. The probe is made of modified oligonucleotides and binds specifically to its complementary strand. When single-stranded, the probe is not cleaved by the nuclease; once bound to the complementary strand, the nuclease cleaves the probe, generating a fluorescence signal. As the reaction proceeds, new probes bind to complementary strands and continue new cycles, accumulating fluorescence. The instrument then detects the fluorescence signal and automatically analyzes the result.','ប្រព័ន្ធរាយការណ៍ RHAM មានអង់ស៊ីម nuclease និងប្រូប (probe) មួយ។ ប្រូបត្រូវបានផលិតពី oligonucleotides ដែលបានកែប្រែ ហើយភ្ជាប់ដោយជាក់លាក់ជាមួយខ្សែបំពេញបន្ថែមរបស់វា។ ពេលនៅជាខ្សែតែមួយ ប្រូបមិនត្រូវបានកាត់ដោយ nuclease ទេ។ ពេលភ្ជាប់ជាមួយខ្សែបំពេញបន្ថែមហើយ nuclease កាត់ប្រូប បង្កើតសញ្ញាពន្លឺ (fluorescence)។ នៅពេលប្រតិកម្មដំណើរការ ប្រូបថ្មីភ្ជាប់ជាមួយខ្សែបំពេញបន្ថែម ហើយបន្តវដ្តថ្មី ប្រមូលផ្តុំហ្វ្លុយអូរ៉េសង់។ បន្ទាប់មកម៉ាស៊ីនរកឃើញសញ្ញាពន្លឺ (fluorescence) ហើយវិភាគលទ្ធផលដោយស្វ័យប្រវត្តិ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-11-Q05','PI-11','Product Information','rham technology explain','ពន្យល់បច្ចេកវិទ្យា rham','Pluslife POCT products are based on Pluslife''s proprietary RHAM technology, which is an optimization built on LAMP technology.
The RHAM reporting system consists of a nuclease and a probe. The probe is made of modified oligonucleotides and binds specifically to its complementary strand. When single-stranded, the probe is not cleaved by the nuclease; once bound to the complementary strand, the nuclease cleaves the probe, generating a fluorescence signal. As the reaction proceeds, new probes bind to complementary strands and continue new cycles, accumulating fluorescence. The instrument then detects the fluorescence signal and automatically analyzes the result.','ផលិតផល POCT របស់ Pluslife ផ្អែកលើបច្ចេកវិទ្យា RHAM ជាកម្មសិទ្ធិផ្ទាល់របស់ Pluslife ដែលជាការធ្វើឲ្យប្រសើរឡើងដោយផ្អែកលើបច្ចេកវិទ្យា LAMP។
ប្រព័ន្ធរាយការណ៍ RHAM មានអង់ស៊ីម nuclease និងប្រូប (probe) មួយ។ ប្រូបត្រូវបានផលិតពី oligonucleotides ដែលបានកែប្រែ ហើយភ្ជាប់ដោយជាក់លាក់ជាមួយខ្សែបំពេញបន្ថែមរបស់វា។ ពេលនៅជាខ្សែតែមួយ ប្រូបមិនត្រូវបានកាត់ដោយ nuclease ទេ។ ពេលភ្ជាប់ជាមួយខ្សែបំពេញបន្ថែមហើយ nuclease កាត់ប្រូប បង្កើតសញ្ញាពន្លឺ (fluorescence)។ នៅពេលប្រតិកម្មដំណើរការ ប្រូបថ្មីភ្ជាប់ជាមួយខ្សែបំពេញបន្ថែម ហើយបន្តវដ្តថ្មី ប្រមូលផ្តុំហ្វ្លុយអូរ៉េសង់។ បន្ទាប់មកម៉ាស៊ីនរកឃើញសញ្ញាពន្លឺ (fluorescence) ហើយវិភាគលទ្ធផលដោយស្វ័យប្រវត្តិ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-12','PI-12','Product Information','Releasing agent tube looks only partly filled (2 mL in a 5 mL tube)','បំពង់សារធាតុបញ្ចេញមើលទៅពេញតែមួយផ្នែក (2 mL ក្នុងបំពង់ 5 mL)','To prevent the diluent from splashing while mixing the sampling swab, the tube leaves some headspace; also, when squeezing the tube to load the sample, sufficient space is needed to control the loading volume. It is normal for the tube to be filled to about 40% of its capacity before opening.','ដើម្បីការពារកុំឲ្យសារធាតុរំលាយ (diluent) ខ្ទាតពេលកូរដំបងសំឡីយកសំណាក បំពង់ទុកចន្លោះទទេខ្លះ។ ម្យ៉ាងទៀត ពេលច្របាច់បំពង់ដើម្បីដាក់សំណាក ត្រូវការចន្លោះគ្រប់គ្រាន់ ដើម្បីគ្រប់គ្រងបរិមាណដាក់ចូល។ វាជារឿងធម្មតាដែលបំពង់ត្រូវបានបំពេញប្រហែល 40% នៃចំណុះ មុនពេលបើក។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-12-Q01','PI-12','Product Information','The releasing agent tube is only half full. Is something wrong?','បំពង់សារធាតុបញ្ចេញពេញតែពាក់កណ្តាល។ តើមានអ្វីមិនធម្មតាឬ?','No. It is normal for the tube to be filled to about 40% of its capacity before opening. To prevent the diluent from splashing while mixing the sampling swab, the tube leaves some headspace; also, when squeezing the tube to load the sample, sufficient space is needed to control the loading volume.','មិនមែនទេ។ វាជារឿងធម្មតាដែលបំពង់ត្រូវបានបំពេញប្រហែល 40% នៃចំណុះ មុនពេលបើក។ ដើម្បីការពារកុំឲ្យសារធាតុរំលាយ (diluent) ខ្ទាតពេលកូរដំបងសំឡីយកសំណាក បំពង់ទុកចន្លោះទទេខ្លះ។ ម្យ៉ាងទៀត ពេលច្របាច់បំពង់ដើម្បីដាក់សំណាក ត្រូវការចន្លោះគ្រប់គ្រាន់ ដើម្បីគ្រប់គ្រងបរិមាណដាក់ចូល។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-12-Q02','PI-12','Product Information','Why is 2 mL releasing agent packed in a 5 mL tube?','ហេតុអ្វីបានជាសារធាតុបញ្ចេញ 2 mL ត្រូវបានវេចខ្ចប់ក្នុងបំពង់ 5 mL?','To prevent the diluent from splashing while mixing the sampling swab, the tube leaves some headspace; also, when squeezing the tube to load the sample, sufficient space is needed to control the loading volume. It is normal for the tube to be filled to about 40% of its capacity before opening.','ដើម្បីការពារកុំឲ្យសារធាតុរំលាយ (diluent) ខ្ទាតពេលកូរដំបងសំឡីយកសំណាក បំពង់ទុកចន្លោះទទេខ្លះ។ ម្យ៉ាងទៀត ពេលច្របាច់បំពង់ដើម្បីដាក់សំណាក ត្រូវការចន្លោះគ្រប់គ្រាន់ ដើម្បីគ្រប់គ្រងបរិមាណដាក់ចូល។ វាជារឿងធម្មតាដែលបំពង់ត្រូវបានបំពេញប្រហែល 40% នៃចំណុះ មុនពេលបើក។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-12-Q03','PI-12','Product Information','tube look not full, missing liquid?','បំពង់មើលទៅមិនពេញ ខ្វះរាវឬ?','No. It is normal for the tube to be filled to about 40% of its capacity before opening.','មិនមែនទេ។ វាជារឿងធម្មតាដែលបំពង់ត្រូវបានបំពេញប្រហែល 40% នៃចំណុះ មុនពេលបើក។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-12-Q04','PI-12','Product Information','Is it normal that the tube is only about 40% filled?','តើជារឿងធម្មតាឬទេ ដែលបំពង់ពេញតែប្រហែល 40%?','Yes. To prevent the diluent from splashing while mixing the sampling swab, the tube leaves some headspace; also, when squeezing the tube to load the sample, sufficient space is needed to control the loading volume. It is normal for the tube to be filled to about 40% of its capacity before opening.','បាទ/ចាស។ ដើម្បីការពារកុំឲ្យសារធាតុរំលាយ (diluent) ខ្ទាតពេលកូរដំបងសំឡីយកសំណាក បំពង់ទុកចន្លោះទទេខ្លះ។ ម្យ៉ាងទៀត ពេលច្របាច់បំពង់ដើម្បីដាក់សំណាក ត្រូវការចន្លោះគ្រប់គ្រាន់ ដើម្បីគ្រប់គ្រងបរិមាណដាក់ចូល។ វាជារឿងធម្មតាដែលបំពង់ត្រូវបានបំពេញប្រហែល 40% នៃចំណុះ មុនពេលបើក។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-12-Q05','PI-12','Product Information','why big tube small liquid','ហេតុអ្វីបំពង់ធំ រាវតិច','To prevent the diluent from splashing while mixing the sampling swab, the tube leaves some headspace; also, when squeezing the tube to load the sample, sufficient space is needed to control the loading volume. It is normal for the tube to be filled to about 40% of its capacity before opening.','ដើម្បីការពារកុំឲ្យសារធាតុរំលាយ (diluent) ខ្ទាតពេលកូរដំបងសំឡីយកសំណាក បំពង់ទុកចន្លោះទទេខ្លះ។ ម្យ៉ាងទៀត ពេលច្របាច់បំពង់ដើម្បីដាក់សំណាក ត្រូវការចន្លោះគ្រប់គ្រាន់ ដើម្បីគ្រប់គ្រងបរិមាណដាក់ចូល។ វាជារឿងធម្មតាដែលបំពង់ត្រូវបានបំពេញប្រហែល 40% នៃចំណុះ មុនពេលបើក។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-13','PI-13','Product Information','Worker asks at what temperature cards can be stored or used','បុគ្គលិកសួរថា កាតអាចរក្សាទុក ឬប្រើនៅសីតុណ្ហភាពប៉ុន្មាន','MTB test cards: storage 0–40 °C, operating 10–30 °C. Other test cards: storage 2 °C–28 °C, operating 15 °C–28 °C.','កាតតេស្ត MTB៖ ការរក្សាទុក 0–40 °C សីតុណ្ហភាពប្រតិបត្តិការ 10–30 °C។ កាតតេស្តផ្សេងទៀត៖ ការរក្សាទុក 2 °C–28 °C សីតុណ្ហភាពប្រតិបត្តិការ 15 °C–28 °C។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-13-Q01','PI-13','Product Information','At what temperature should I store the TB test cards?','តើខ្ញុំគួររក្សាទុកកាតតេស្តជំងឺរបេងនៅសីតុណ្ហភាពប៉ុន្មាន?','MTB test cards: storage 0–40 °C.','កាតតេស្ត MTB៖ ការរក្សាទុក 0–40 °C។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-13-Q02','PI-13','Product Information','Do the MTB cards need a fridge?','តើកាត MTB ត្រូវការទូទឹកកកឬទេ?','No. MTB test cards can be stored at 0–40 °C.','មិនមែនទេ។ កាតតេស្ត MTB អាចរក្សាទុកនៅ 0–40 °C។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-13-Q03','PI-13','Product Information','What room temperature is OK when I run the test with an MTB card?','តើសីតុណ្ហភាពបន្ទប់ប៉ុន្មានទើបបាន ពេលខ្ញុំធ្វើតេស្តជាមួយកាត MTB?','MTB test cards: operating temperature 10–30 °C.','កាតតេស្ត MTB៖ សីតុណ្ហភាពប្រតិបត្តិការ 10–30 °C។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-13-Q04','PI-13','Product Information','Our room is 35 °C, can I still run the MTB test?','បន្ទប់យើង 35 °C តើខ្ញុំនៅតែអាចធ្វើតេស្ត MTB បានទេ?','No. The operating temperature for MTB test cards is 10–30 °C.','មិនមែនទេ។ សីតុណ្ហភាពប្រតិបត្តិការសម្រាប់កាតតេស្ត MTB គឺ 10–30 °C។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-13-Q05','PI-13','Product Information','Can I keep the MTB cards in the storeroom at 38 °C?','តើខ្ញុំអាចទុកកាត MTB ក្នុងបន្ទប់ស្តុកនៅ 38 °C បានទេ?','Yes. MTB test cards can be stored at 0–40 °C.','បាទ/ចាស។ កាតតេស្ត MTB អាចរក្សាទុកនៅ 0–40 °C។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-13-Q06','PI-13','Product Information','card storage temp','សីតុណ្ហភាពរក្សាទុកកាត','MTB test cards: storage 0–40 °C, operating 10–30 °C. Other test cards: storage 2 °C–28 °C, operating 15 °C–28 °C.','កាតតេស្ត MTB៖ ការរក្សាទុក 0–40 °C សីតុណ្ហភាពប្រតិបត្តិការ 10–30 °C។ កាតតេស្តផ្សេងទៀត៖ ការរក្សាទុក 2 °C–28 °C សីតុណ្ហភាពប្រតិបត្តិការ 15 °C–28 °C។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-14','PI-14','Product Information','Worker asks which parts of the system can be reused','បុគ្គលិកសួរថា តើផ្នែកណាខ្លះនៃប្រព័ន្ធអាចប្រើឡើងវិញបាន','The instrument is reusable; test cards are single-use. One test card per person per test.','ម៉ាស៊ីនអាចប្រើឡើងវិញបាន។ កាតតេស្តប្រើតែម្តង។ កាតតេស្តមួយ សម្រាប់មនុស្សម្នាក់ ក្នុងតេស្តមួយដង។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-14-Q01','PI-14','Product Information','Are Pluslife products reusable?','តើផលិតផល Pluslife អាចប្រើឡើងវិញបានទេ?','Not all of them. The instrument is reusable; test cards are single-use. One test card per person per test.','មិនមែនទាំងអស់ទេ។ ម៉ាស៊ីនអាចប្រើឡើងវិញបាន។ កាតតេស្តប្រើតែម្តង។ កាតតេស្តមួយ សម្រាប់មនុស្សម្នាក់ ក្នុងតេស្តមួយដង។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-14-Q02','PI-14','Product Information','Can I use one card for two patients?','តើខ្ញុំអាចប្រើកាតមួយសម្រាប់អ្នកជំងឺពីរនាក់បានទេ?','No. Test cards are single-use. One test card per person per test.','មិនបានទេ។ កាតតេស្តប្រើតែម្តង។ កាតតេស្តមួយ សម្រាប់មនុស្សម្នាក់ ក្នុងតេស្តមួយដង។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-14-Q03','PI-14','Product Information','Is the test card reusable?','តើកាតតេស្តអាចប្រើឡើងវិញបានទេ?','No. Test cards are single-use. One test card per person per test.','មិនបានទេ។ កាតតេស្តប្រើតែម្តង។ កាតតេស្តមួយ សម្រាប់មនុស្សម្នាក់ ក្នុងតេស្តមួយដង។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-14-Q04','PI-14','Product Information','the device can use many time?','ម៉ាស៊ីនប្រើបានច្រើនដងឬ?','Yes. The instrument is reusable; the test cards are single-use.','បាទ/ចាស។ ម៉ាស៊ីនអាចប្រើឡើងវិញបាន។ កាតតេស្តប្រើតែម្តង។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-14-Q05','PI-14','Product Information','one card how many test','កាតមួយ តេស្តបានប៉ុន្មាន','One test card per person per test — test cards are single-use.','កាតតេស្តមួយ សម្រាប់មនុស្សម្នាក់ ក្នុងតេស្តមួយដង — កាតតេស្តប្រើតែម្តង។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-15','PI-15','Product Information','Worker worries the heating module could overheat','បុគ្គលិកបារម្ភថាម៉ូឌុលកំដៅអាចឡើងកម្តៅហួសកម្រិត','The device has a built-in temperature protection device that automatically provides real-time protection when the alarm temperature is exceeded, so there is no need to worry about temperature runaway.','ម៉ាស៊ីនមានឧបករណ៍ការពារសីតុណ្ហភាពដែលភ្ជាប់មកស្រាប់ ដែលផ្តល់ការការពារតាមពេលវេលាជាក់ស្តែងដោយស្វ័យប្រវត្តិ នៅពេលលើសសីតុណ្ហភាពរោទិ៍ ដូច្នេះមិនចាំបាច់បារម្ភអំពីសីតុណ្ហភាពកើនឡើងហួសការគ្រប់គ្រងទេ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-15-Q01','PI-15','Product Information','Can the device overheat because of the heater?','តើម៉ាស៊ីនអាចឡើងកម្តៅហួសកម្រិត ដោយសារឧបករណ៍កំដៅឬទេ?','No. The device has a built-in temperature protection device that automatically provides real-time protection when the alarm temperature is exceeded, so there is no need to worry about temperature runaway.','មិនចាំបាច់ទេ។ ម៉ាស៊ីនមានឧបករណ៍ការពារសីតុណ្ហភាពដែលភ្ជាប់មកស្រាប់ ដែលផ្តល់ការការពារតាមពេលវេលាជាក់ស្តែងដោយស្វ័យប្រវត្តិ នៅពេលលើសសីតុណ្ហភាពរោទិ៍ ដូច្នេះមិនចាំបាច់បារម្ភអំពីសីតុណ្ហភាពកើនឡើងហួសការគ្រប់គ្រងទេ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-15-Q02','PI-15','Product Information','Is there a risk of temperature runaway?','តើមានហានិភ័យសីតុណ្ហភាពកើនឡើងហួសការគ្រប់គ្រងឬទេ?','No. The device has a built-in temperature protection device that automatically provides real-time protection when the alarm temperature is exceeded, so there is no need to worry about temperature runaway.','មិនចាំបាច់ទេ។ ម៉ាស៊ីនមានឧបករណ៍ការពារសីតុណ្ហភាពដែលភ្ជាប់មកស្រាប់ ដែលផ្តល់ការការពារតាមពេលវេលាជាក់ស្តែងដោយស្វ័យប្រវត្តិ នៅពេលលើសសីតុណ្ហភាពរោទិ៍ ដូច្នេះមិនចាំបាច់បារម្ភអំពីសីតុណ្ហភាពកើនឡើងហួសការគ្រប់គ្រងទេ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-15-Q03','PI-15','Product Information','The device gets warm, is it dangerous?','ម៉ាស៊ីនក្តៅ តើគ្រោះថ្នាក់ឬទេ?','Not sure what you are feeling, but the device has a built-in temperature protection device that automatically provides real-time protection when the alarm temperature is exceeded.','មិនច្បាស់ថាអ្នកកំពុងមានអារម្មណ៍អ្វីទេ ប៉ុន្តែម៉ាស៊ីនមានឧបករណ៍ការពារសីតុណ្ហភាពដែលភ្ជាប់មកស្រាប់ ដែលផ្តល់ការការពារតាមពេលវេលាជាក់ស្តែងដោយស្វ័យប្រវត្តិ នៅពេលលើសសីតុណ្ហភាពរោទិ៍។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-15-Q04','PI-15','Product Information','Does the MiniDock have overheat protection?','តើ MiniDock មានការការពារកម្តៅហួសកម្រិតឬទេ?','Yes. The device has a built-in temperature protection device that automatically provides real-time protection when the alarm temperature is exceeded, so there is no need to worry about temperature runaway.','បាទ/ចាស។ ម៉ាស៊ីនមានឧបករណ៍ការពារសីតុណ្ហភាពដែលភ្ជាប់មកស្រាប់ ដែលផ្តល់ការការពារតាមពេលវេលាជាក់ស្តែងដោយស្វ័យប្រវត្តិ នៅពេលលើសសីតុណ្ហភាពរោទិ៍ ដូច្នេះមិនចាំបាច់បារម្ភអំពីសីតុណ្ហភាពកើនឡើងហួសការគ្រប់គ្រងទេ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-15-Q05','PI-15','Product Information','heater safe?','ឧបករណ៍កំដៅមានសុវត្ថិភាពឬ?','The device has a built-in temperature protection device that automatically provides real-time protection when the alarm temperature is exceeded, so there is no need to worry about temperature runaway.','ម៉ាស៊ីនមានឧបករណ៍ការពារសីតុណ្ហភាពដែលភ្ជាប់មកស្រាប់ ដែលផ្តល់ការការពារតាមពេលវេលាជាក់ស្តែងដោយស្វ័យប្រវត្តិ នៅពេលលើសសីតុណ្ហភាពរោទិ៍ ដូច្នេះមិនចាំបាច់បារម្ភអំពីសីតុណ្ហភាពកើនឡើងហួសការគ្រប់គ្រងទេ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-16','PI-16','Product Information','Worker asks where to find sensitivity, specificity or LOD','បុគ្គលិកសួរថា រកភាពរសើប ភាពជាក់លាក់ ឬ LOD នៅឯណា','In the IFU (Instructions for Use) of the corresponding product. Performance parameters may differ between products; technical confirmation and external replies should be based on the corresponding product''s IFU.','នៅក្នុង IFU (សៀវភៅណែនាំការប្រើប្រាស់) នៃផលិតផលដែលត្រូវគ្នា។ ប៉ារ៉ាម៉ែត្រសមត្ថភាពអាចខុសគ្នារវាងផលិតផល ការបញ្ជាក់បច្ចេកទេស និងការឆ្លើយតបទៅខាងក្រៅ ត្រូវផ្អែកលើ IFU នៃផលិតផលដែលត្រូវគ្នា។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-16-Q01','PI-16','Product Information','Where can I find the sensitivity and specificity of the test card?','តើខ្ញុំអាចរកភាពរសើប និងភាពជាក់លាក់នៃកាតតេស្តនៅឯណា?','In the IFU (Instructions for Use) of the corresponding product. Performance parameters may differ between products; technical confirmation and external replies should be based on the corresponding product''s IFU.','នៅក្នុង IFU (សៀវភៅណែនាំការប្រើប្រាស់) នៃផលិតផលដែលត្រូវគ្នា។ ប៉ារ៉ាម៉ែត្រសមត្ថភាពអាចខុសគ្នារវាងផលិតផល ការបញ្ជាក់បច្ចេកទេស និងការឆ្លើយតបទៅខាងក្រៅ ត្រូវផ្អែកលើ IFU នៃផលិតផលដែលត្រូវគ្នា។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-16-Q02','PI-16','Product Information','What is the LOD of the card?','តើ LOD របស់កាតគឺប៉ុន្មាន?','Please check the IFU (Instructions for Use) of the corresponding product. Performance parameters may differ between products.','សូមពិនិត្យ IFU (សៀវភៅណែនាំការប្រើប្រាស់) នៃផលិតផលដែលត្រូវគ្នា។ ប៉ារ៉ាម៉ែត្រសមត្ថភាពអាចខុសគ្នារវាងផលិតផល។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-16-Q03','PI-16','Product Information','where LOD info','ព័ត៌មាន LOD នៅឯណា','In the IFU (Instructions for Use) of the corresponding product. Performance parameters may differ between products; technical confirmation and external replies should be based on the corresponding product''s IFU.','នៅក្នុង IFU (សៀវភៅណែនាំការប្រើប្រាស់) នៃផលិតផលដែលត្រូវគ្នា។ ប៉ារ៉ាម៉ែត្រសមត្ថភាពអាចខុសគ្នារវាងផលិតផល ការបញ្ជាក់បច្ចេកទេស និងការឆ្លើយតបទៅខាងក្រៅ ត្រូវផ្អែកលើ IFU នៃផលិតផលដែលត្រូវគ្នា។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-16-Q04','PI-16','Product Information','Is the sensitivity the same for all Pluslife cards?','តើភាពរសើបដូចគ្នាសម្រាប់កាតតេស្ត Pluslife ទាំងអស់ឬទេ?','No. Performance parameters may differ between products; check the IFU of the corresponding product.','មិនមែនទេ។ ប៉ារ៉ាម៉ែត្រសមត្ថភាពអាចខុសគ្នារវាងផលិតផល សូមពិនិត្យ IFU នៃផលិតផលដែលត្រូវគ្នា។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-17','PI-17','Product Information','Worker asks how this test differs from an antigen (rapid) test','បុគ្គលិកសួរថា តេស្តនេះខុសពីតេស្តអង់ទីហ្សែន (antigen) (តេស្តរហ័ស) យ៉ាងណា','Nucleic acid testing and antigen testing are two different methods. Compared with antigen testing, nucleic acid tests such as PCR and Pluslife have higher sensitivity: the target is continuously replicated during the test, so samples with very low viral load can be detected. Antigen tests detect proteins on the virus surface, which do not replicate or amplify, so more virus is needed for a positive result and false negatives are more common.','ការធ្វើតេស្តអាស៊ីតនុយក្លេអ៊ីក និងការធ្វើតេស្តអង់ទីហ្សែន (antigen) ជាវិធីសាស្ត្រពីរផ្សេងគ្នា។ បើធៀបនឹងតេស្តអង់ទីហ្សែន តេស្តអាស៊ីតនុយក្លេអ៊ីកដូចជា PCR និង Pluslife មានភាពរសើបខ្ពស់ជាង៖ គោលដៅត្រូវបានចម្លងជាបន្តបន្ទាប់ក្នុងពេលតេស្ត ដូច្នេះអាចរកឃើញសំណាកដែលមានបន្ទុកមេរោគទាបខ្លាំង។ តេស្តអង់ទីហ្សែនរកប្រូតេអ៊ីនលើផ្ទៃមេរោគ ដែលមិនចម្លង ឬពង្រីកបាន ដូច្នេះត្រូវការមេរោគច្រើនជាងដើម្បីបានលទ្ធផលវិជ្ជមាន ហើយលទ្ធផលអវិជ្ជមានក្លែងក្លាយកើតមានញឹកញាប់ជាង។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-17-Q01','PI-17','Product Information','What is the difference between this test and an antigen test?','តើតេស្តនេះខុសពីតេស្តអង់ទីហ្សែន (antigen) យ៉ាងណា?','Nucleic acid testing and antigen testing are two different methods. Compared with antigen testing, nucleic acid tests such as PCR and Pluslife have higher sensitivity: the target is continuously replicated during the test, so samples with very low viral load can be detected. Antigen tests detect proteins on the virus surface, which do not replicate or amplify, so more virus is needed for a positive result and false negatives are more common.','ការធ្វើតេស្តអាស៊ីតនុយក្លេអ៊ីក និងការធ្វើតេស្តអង់ទីហ្សែន (antigen) ជាវិធីសាស្ត្រពីរផ្សេងគ្នា។ បើធៀបនឹងតេស្តអង់ទីហ្សែន តេស្តអាស៊ីតនុយក្លេអ៊ីកដូចជា PCR និង Pluslife មានភាពរសើបខ្ពស់ជាង៖ គោលដៅត្រូវបានចម្លងជាបន្តបន្ទាប់ក្នុងពេលតេស្ត ដូច្នេះអាចរកឃើញសំណាកដែលមានបន្ទុកមេរោគទាបខ្លាំង។ តេស្តអង់ទីហ្សែនរកប្រូតេអ៊ីនលើផ្ទៃមេរោគ ដែលមិនចម្លង ឬពង្រីកបាន ដូច្នេះត្រូវការមេរោគច្រើនជាងដើម្បីបានលទ្ធផលវិជ្ជមាន ហើយលទ្ធផលអវិជ្ជមានក្លែងក្លាយកើតមានញឹកញាប់ជាង។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-17-Q02','PI-17','Product Information','Is Pluslife more sensitive than a rapid antigen test?','តើ Pluslife រសើបជាងតេស្តអង់ទីហ្សែនរហ័សឬទេ?','Yes. Compared with antigen testing, nucleic acid tests such as PCR and Pluslife have higher sensitivity: the target is continuously replicated during the test, so samples with very low viral load can be detected.','បាទ/ចាស។ បើធៀបនឹងតេស្តអង់ទីហ្សែន តេស្តអាស៊ីតនុយក្លេអ៊ីកដូចជា PCR និង Pluslife មានភាពរសើបខ្ពស់ជាង៖ គោលដៅត្រូវបានចម្លងជាបន្តបន្ទាប់ក្នុងពេលតេស្ត ដូច្នេះអាចរកឃើញសំណាកដែលមានបន្ទុកមេរោគទាបខ្លាំង។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-17-Q03','PI-17','Product Information','Is Pluslife an antigen test?','តើ Pluslife ជាតេស្តអង់ទីហ្សែនឬទេ?','No. Pluslife is a nucleic acid test. Nucleic acid testing and antigen testing are two different methods. Compared with antigen testing, nucleic acid tests such as PCR and Pluslife have higher sensitivity: the target is continuously replicated during the test, so samples with very low viral load can be detected. Antigen tests detect proteins on the virus surface, which do not replicate or amplify, so more virus is needed for a positive result and false negatives are more common.','មិនមែនទេ។ Pluslife ជាតេស្តអាស៊ីតនុយក្លេអ៊ីក។ ការធ្វើតេស្តអាស៊ីតនុយក្លេអ៊ីក និងការធ្វើតេស្តអង់ទីហ្សែន (antigen) ជាវិធីសាស្ត្រពីរផ្សេងគ្នា។ បើធៀបនឹងតេស្តអង់ទីហ្សែន តេស្តអាស៊ីតនុយក្លេអ៊ីកដូចជា PCR និង Pluslife មានភាពរសើបខ្ពស់ជាង៖ គោលដៅត្រូវបានចម្លងជាបន្តបន្ទាប់ក្នុងពេលតេស្ត ដូច្នេះអាចរកឃើញសំណាកដែលមានបន្ទុកមេរោគទាបខ្លាំង។ តេស្តអង់ទីហ្សែនរកប្រូតេអ៊ីនលើផ្ទៃមេរោគ ដែលមិនចម្លង ឬពង្រីកបាន ដូច្នេះត្រូវការមេរោគច្រើនជាងដើម្បីបានលទ្ធផលវិជ្ជមាន ហើយលទ្ធផលអវិជ្ជមានក្លែងក្លាយកើតមានញឹកញាប់ជាង។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-17-Q04','PI-17','Product Information','why antigen test more false negative','ហេតុអ្វីតេស្តអង់ទីហ្សែនមានលទ្ធផលអវិជ្ជមានក្លែងក្លាយច្រើនជាង','Antigen tests detect proteins on the virus surface, which do not replicate or amplify, so more virus is needed for a positive result and false negatives are more common.','តេស្តអង់ទីហ្សែនរកប្រូតេអ៊ីនលើផ្ទៃមេរោគ ដែលមិនចម្លង ឬពង្រីកបាន ដូច្នេះត្រូវការមេរោគច្រើនជាងដើម្បីបានលទ្ធផលវិជ្ជមាន ហើយលទ្ធផលអវិជ្ជមានក្លែងក្លាយកើតមានញឹកញាប់ជាង។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-01','QC-01','Quality Control','Worker asks for the QC video','បុគ្គលិកសុំវីដេអូ QC','https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-01-Q01','QC-01','Quality Control','Is there a video on how to run QC?','តើមានវីដេអូអំពីរបៀបធ្វើ QC ឬទេ?','Yes: https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','បាទ/ចាស៖ https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-01-Q02','QC-01','Quality Control','qc video','វីដេអូ qc','https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-01-Q03','QC-01','Quality Control','How to run a quality control?','តើធ្វើការត្រួតពិនិត្យគុណភាព (QC) ដោយរបៀបណា?','Video: https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','វីដេអូ៖ https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-02','QC-02','Quality Control','Worker asks what QC is for and when to run it','បុគ្គលិកសួរថា QC សម្រាប់អ្វី ហើយត្រូវធ្វើនៅពេលណា','QC is used to monitor whether the experimental procedures are performed correctly, whether the reagents remain stable, whether the instrument is functioning properly, and whether there is any environmental contamination.
The frequency of QC testing depends on the specific requirements and management protocols of the laboratory. If there are no specific requirements, QC testing is recommended when changing kit batches, during annual instrument performance checks, and when laboratory contamination is suspected.','QC (ការត្រួតពិនិត្យគុណភាព) ប្រើដើម្បីតាមដានថាតើនីតិវិធីពិសោធន៍ត្រូវបានអនុវត្តត្រឹមត្រូវឬអត់ សារធាតុរ៉េអាក់ទីហ្វនៅមានស្ថិរភាពឬអត់ ម៉ាស៊ីនដំណើរការបានល្អឬអត់ និងមានការចម្លងរោគពីបរិស្ថានឬអត់។
ភាពញឹកញាប់នៃការធ្វើតេស្ត QC អាស្រ័យលើតម្រូវការជាក់លាក់ និងពិធីសារគ្រប់គ្រងរបស់មន្ទីរពិសោធន៍។ បើគ្មានតម្រូវការជាក់លាក់ទេ ណែនាំឲ្យធ្វើតេស្ត QC ពេលដូរឡូ (batch) ឈុតតេស្ត ក្នុងអំឡុងការត្រួតពិនិត្យសមត្ថភាពម៉ាស៊ីនប្រចាំឆ្នាំ និងពេលសង្ស័យថាមន្ទីរពិសោធន៍មានការចម្លងរោគ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-02-Q01','QC-02','Quality Control','Does Pluslife have quality controls?','តើ Pluslife មានសារធាតុត្រួតពិនិត្យគុណភាព (QC) ឬទេ?','Yes. QC is used to monitor whether the experimental procedures are performed correctly, whether the reagents remain stable, whether the instrument is functioning properly, and whether there is any environmental contamination.','បាទ/ចាស។ QC (ការត្រួតពិនិត្យគុណភាព) ប្រើដើម្បីតាមដានថាតើនីតិវិធីពិសោធន៍ត្រូវបានអនុវត្តត្រឹមត្រូវឬអត់ សារធាតុរ៉េអាក់ទីហ្វនៅមានស្ថិរភាពឬអត់ ម៉ាស៊ីនដំណើរការបានល្អឬអត់ និងមានការចម្លងរោគពីបរិស្ថានឬអត់។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-02-Q02','QC-02','Quality Control','When do I need to run QC?','តើខ្ញុំត្រូវធ្វើ QC នៅពេលណា?','If there are no specific requirements, QC testing is recommended when changing kit batches, during annual instrument performance checks, and when laboratory contamination is suspected.','បើគ្មានតម្រូវការជាក់លាក់ទេ ណែនាំឲ្យធ្វើតេស្ត QC ពេលដូរឡូ (batch) ឈុតតេស្ត ក្នុងអំឡុងការត្រួតពិនិត្យសមត្ថភាពម៉ាស៊ីនប្រចាំឆ្នាំ និងពេលសង្ស័យថាមន្ទីរពិសោធន៍មានការចម្លងរោគ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-02-Q03','QC-02','Quality Control','Do I need QC every day?','តើខ្ញុំត្រូវការ QC រាល់ថ្ងៃឬទេ?','Not sure — it depends on the specific requirements and management protocols of the laboratory. If there are none, QC is recommended when changing kit batches, during annual instrument checks, and when contamination is suspected.','មិនច្បាស់ទេ — វាអាស្រ័យលើតម្រូវការជាក់លាក់ និងពិធីសារគ្រប់គ្រងរបស់មន្ទីរពិសោធន៍។ បើគ្មានទេ ណែនាំឲ្យធ្វើ QC ពេលដូរឡូ (batch) ឈុតតេស្ត ក្នុងអំឡុងការត្រួតពិនិត្យម៉ាស៊ីនប្រចាំឆ្នាំ និងពេលសង្ស័យថាមានការចម្លងរោគ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-02-Q04','QC-02','Quality Control','New kit batch arrived. Should I run QC?','ឡូ (batch) ឈុតតេស្តថ្មីបានមកដល់។ តើខ្ញុំគួរធ្វើ QC ឬទេ?','Yes. QC testing is recommended when changing kit batches.','បាទ/ចាស។ ណែនាំឲ្យធ្វើតេស្ត QC ពេលដូរឡូ (batch) ឈុតតេស្ត។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-02-Q05','QC-02','Quality Control','what qc for','qc សម្រាប់អ្វី','QC is used to monitor whether the experimental procedures are performed correctly, whether the reagents remain stable, whether the instrument is functioning properly, and whether there is any environmental contamination.','QC (ការត្រួតពិនិត្យគុណភាព) ប្រើដើម្បីតាមដានថាតើនីតិវិធីពិសោធន៍ត្រូវបានអនុវត្តត្រឹមត្រូវឬអត់ សារធាតុរ៉េអាក់ទីហ្វនៅមានស្ថិរភាពឬអត់ ម៉ាស៊ីនដំណើរការបានល្អឬអត់ និងមានការចម្លងរោគពីបរិស្ថានឬអត់។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-03','QC-03','Quality Control','Worker asks what the QC material is, how to store it, or what is in a set','បុគ្គលិកសួរថា សារធាតុ QC ជាអ្វី របៀបរក្សាទុក ឬក្នុងមួយឈុតមានអ្វីខ្លះ','The quality control material is a plasmid in lyophilized microsphere form, and should be stored at 2–28 °C, valid for 13 months.
Specification: 1 set (1 positive and 1 negative control).','សារធាតុត្រួតពិនិត្យគុណភាព (quality control material) ជា plasmid ក្នុងទម្រង់មីក្រូស្វ៊ែរស្ងួតកក (lyophilized microsphere) ហើយត្រូវរក្សាទុកនៅ 2–28 °C មានសុពលភាព ១៣ ខែ។
លក្ខណៈបច្ចេកទេស៖ ១ ឈុត (ត្រួតពិនិត្យវិជ្ជមាន ១ និងអវិជ្ជមាន ១)។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-03-Q01','QC-03','Quality Control','Is the QC material a plasmid or real bacteria?','តើសារធាតុ QC ជា plasmid ឬបាក់តេរីពិត?','The quality control material is a plasmid in lyophilized microsphere form.','សារធាតុត្រួតពិនិត្យគុណភាព (quality control material) ជា plasmid ក្នុងទម្រង់មីក្រូស្វ៊ែរស្ងួតកក (lyophilized microsphere)។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-03-Q02','QC-03','Quality Control','How do I store the QC?','តើខ្ញុំរក្សាទុក QC ដោយរបៀបណា?','Store at 2–28 °C; valid for 13 months.','រក្សាទុកនៅ 2–28 °C មានសុពលភាព ១៣ ខែ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-03-Q03','QC-03','Quality Control','What is in one QC set?','តើមានអ្វីខ្លះក្នុងឈុត QC មួយ?','1 set = 1 positive and 1 negative control.','១ ឈុត = ការត្រួតពិនិត្យវិជ្ជមាន ១ និងអវិជ្ជមាន ១។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-03-Q04','QC-03','Quality Control','qc expire','qc ផុតកំណត់','Valid for 13 months.','មានសុពលភាព ១៣ ខែ។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-03-Q05','QC-03','Quality Control','Can I keep the QC at 35 °C?','តើខ្ញុំអាចទុក QC នៅ 35 °C បានទេ?','No. The QC material should be stored at 2–28 °C.','មិនបានទេ។ សារធាតុ QC គួររក្សាទុកនៅ 2–28 °C។','Routine','Study focal point (if not solved) – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-04','QC-04','Quality Control','Worker wants to test another company''s QC material on Pluslife','បុគ្គលិកចង់តេស្តសារធាតុ QC របស់ក្រុមហ៊ុនផ្សេងលើ Pluslife','It is not recommended, as the target sequence of quality control materials from other manufacturers may differ from the target region used by Pluslife. Additionally, the preservation medium may contain components that inhibit Pluslife amplification.','មិនណែនាំទេ ព្រោះលំដាប់គោលដៅនៃសារធាតុត្រួតពិនិត្យគុណភាពរបស់ក្រុមហ៊ុនផលិតផ្សេង អាចខុសពីតំបន់គោលដៅដែល Pluslife ប្រើ។ ម្យ៉ាងទៀត ឧបករណ៍រក្សាសំណាក (preservation medium) អាចមានសមាសធាតុដែលរារាំងការពង្រីករបស់ Pluslife។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-04-Q01','QC-04','Quality Control','Can I use QC from another company with Pluslife cards?','តើខ្ញុំអាចប្រើ QC របស់ក្រុមហ៊ុនផ្សេងជាមួយកាត Pluslife បានទេ?','No. It is not recommended, as the target sequence of quality control materials from other manufacturers may differ from the target region used by Pluslife. Additionally, the preservation medium may contain components that inhibit Pluslife amplification.','មិនបានទេ។ មិនណែនាំទេ ព្រោះលំដាប់គោលដៅនៃសារធាតុត្រួតពិនិត្យគុណភាពរបស់ក្រុមហ៊ុនផលិតផ្សេង អាចខុសពីតំបន់គោលដៅដែល Pluslife ប្រើ។ ម្យ៉ាងទៀត ឧបករណ៍រក្សាសំណាក (preservation medium) អាចមានសមាសធាតុដែលរារាំងការពង្រីករបស់ Pluslife។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-04-Q02','QC-04','Quality Control','other brand control ok?','សារធាតុត្រួតពិនិត្យម៉ាកផ្សេង បានទេ?','No. It is not recommended, as the target sequence of quality control materials from other manufacturers may differ from the target region used by Pluslife. Additionally, the preservation medium may contain components that inhibit Pluslife amplification.','មិនបានទេ។ មិនណែនាំទេ ព្រោះលំដាប់គោលដៅនៃសារធាតុត្រួតពិនិត្យគុណភាពរបស់ក្រុមហ៊ុនផលិតផ្សេង អាចខុសពីតំបន់គោលដៅដែល Pluslife ប្រើ។ ម្យ៉ាងទៀត ឧបករណ៍រក្សាសំណាក (preservation medium) អាចមានសមាសធាតុដែលរារាំងការពង្រីករបស់ Pluslife។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-04-Q03','QC-04','Quality Control','Why doesn''t the Xpert control work on Pluslife?','ហេតុអ្វីបានជាសារធាតុត្រួតពិនិត្យរបស់ Xpert មិនដំណើរការលើ Pluslife?','Not sure for that specific control. In general, QC materials from other manufacturers may have a different target sequence from the Pluslife target region, and the preservation medium may contain components that inhibit Pluslife amplification.','មិនច្បាស់សម្រាប់សារធាតុត្រួតពិនិត្យជាក់លាក់នោះទេ។ ជាទូទៅ សារធាតុ QC របស់ក្រុមហ៊ុនផលិតផ្សេង អាចមានលំដាប់គោលដៅខុសពីតំបន់គោលដៅរបស់ Pluslife ហើយឧបករណ៍រក្សាសំណាក (preservation medium) អាចមានសមាសធាតុដែលរារាំងការពង្រីករបស់ Pluslife។','Routine','Study team – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-05','QC-05','Quality Control','Worker asks how to run QC and read the QC result','បុគ្គលិកសួរពីរបៀបធ្វើ QC និងអានលទ្ធផល QC','1. Transfer the lyophilized bead into a Releasing Agent and mix well.
2. Transfer the Releasing Agent to the card.
3. For PM001 Ultra, just run the QC test as a sample.
The positive control must yield a positive result, and the negative control must yield a negative result.','១. ផ្ទេរគ្រាប់ស្ងួតកក (lyophilized bead) ចូលក្នុងសារធាតុបញ្ចេញ (Releasing Agent) ហើយលាយឲ្យសព្វ។
២. ផ្ទេរសារធាតុបញ្ចេញចូលកាត។
៣. សម្រាប់ PM001 Ultra គ្រាន់តែដំណើរការតេស្ត QC ដូចសំណាកធម្មតា។
ការត្រួតពិនិត្យវិជ្ជមានត្រូវតែផ្តល់លទ្ធផលវិជ្ជមាន ហើយការត្រួតពិនិត្យអវិជ្ជមានត្រូវតែផ្តល់លទ្ធផលអវិជ្ជមាន។','Routine','Study focal point → Pluslife – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-05-Q01','QC-05','Quality Control','How do I do a QC test?','តើខ្ញុំធ្វើតេស្ត QC ដោយរបៀបណា?','1. Transfer the lyophilized bead into a Releasing Agent and mix well.
2. Transfer the Releasing Agent to the card.
3. For PM001 Ultra, just run the QC test as a sample.','១. ផ្ទេរគ្រាប់ស្ងួតកក (lyophilized bead) ចូលក្នុងសារធាតុបញ្ចេញ (Releasing Agent) ហើយលាយឲ្យសព្វ។
២. ផ្ទេរសារធាតុបញ្ចេញចូលកាត។
៣. សម្រាប់ PM001 Ultra គ្រាន់តែដំណើរការតេស្ត QC ដូចសំណាកធម្មតា។','Routine','Study focal point → Pluslife – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-05-Q02','QC-05','Quality Control','Is there a special QC mode on the Ultra?','តើ Ultra មានរបៀប QC ពិសេសឬទេ?','No. For PM001 Ultra, just run the QC test as a sample.','មិនមែនទេ។ សម្រាប់ PM001 Ultra គ្រាន់តែដំណើរការតេស្ត QC ដូចសំណាកធម្មតា។','Routine','Study focal point → Pluslife – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-05-Q03','QC-05','Quality Control','How do I know the QC passed?','តើខ្ញុំដឹងដោយរបៀបណាថា QC ជាប់?','The positive control must yield a positive result, and the negative control must yield a negative result.','ការត្រួតពិនិត្យវិជ្ជមានត្រូវតែផ្តល់លទ្ធផលវិជ្ជមាន ហើយការត្រួតពិនិត្យអវិជ្ជមានត្រូវតែផ្តល់លទ្ធផលអវិជ្ជមាន។','Routine','Study focal point → Pluslife – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-05-Q04','QC-05','Quality Control','Negative control came out positive.','ការត្រួតពិនិត្យអវិជ្ជមានបានវិជ្ជមាន។','The QC did not pass: the negative control must yield a negative result.','QC មិនបានជាប់ទេ៖ ការត្រួតពិនិត្យអវិជ្ជមានត្រូវតែផ្តល់លទ្ធផលអវិជ្ជមាន។','Routine','Study focal point → Pluslife – Roeub Sievlong (Telegram 093 54 55 72)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-05-Q05','QC-05','Quality Control','qc bead how','គ្រាប់ qc ធ្វើម៉េច','Transfer the lyophilized bead into a Releasing Agent and mix well, then transfer the Releasing Agent to the card.','ផ្ទេរគ្រាប់ស្ងួតកក (lyophilized bead) ចូលក្នុងសារធាតុបញ្ចេញ (Releasing Agent) ហើយលាយឲ្យសព្វ បន្ទាប់មកផ្ទេរសារធាតុបញ្ចេញចូលកាត។','Routine','Study focal point → Pluslife – Roeub Sievlong (Telegram 093 54 55 72)');
